#include "editor.hpp"
namespace touch::ui {
void Editor::update_transform(std::optional<Edge> hit_edge){auto& io=ImGui::GetIO();if(!transform||!gesture_before)return;auto mouse=io.MousePos;ImVec2 delta{(mouse.x-gesture_start.x)/zoom,(mouse.y-gesture_start.y)/zoom};ImVec2 pivot{};for(auto [id,l]:gesture_layout){pivot.x+=l.x;pivot.y+=l.y;}if(gesture_layout.empty()){finish_transform(true);return;}pivot.x/=gesture_layout.size();pivot.y/=gesture_layout.size();float scale=std::clamp(1+delta.x/150,.1f,10.f),angle=delta.x/100;if(io.KeyCtrl)angle=std::round(angle/(3.14159265f/12))*(3.14159265f/12);
for(auto [id,l]:gesture_layout){auto& target=document.graph.layout.at(id);if(transform==1){auto snap=[&](float v){return io.KeyCtrl?std::round(v/theme::grid)*theme::grid:v;};target.x=axis==2?l.x:snap(l.x+delta.x);target.y=axis==1?l.y:snap(l.y+delta.y);}else if(transform==2){if(gesture_layout.size()==1&&!reroute(*document.graph.find(id)))target.width=std::clamp(std::round(l.width*scale),112.f,640.f);else{target.x=axis==2?l.x:pivot.x+(l.x-pivot.x)*scale;target.y=axis==1?l.y:pivot.y+(l.y-pivot.y)*scale;}}else{float x=l.x-pivot.x,y=l.y-pivot.y;target.x=pivot.x+x*std::cos(angle)-y*std::sin(angle);target.y=pivot.y+x*std::sin(angle)+y*std::cos(angle);}}
bool confirm=ImGui::IsKeyPressed(ImGuiKey_Enter)||(modal_transform?ImGui::IsMouseClicked(0):ImGui::IsMouseReleased(0));if(confirm){if(transform==1&&hit_edge&&document.selected.size()==1&&std::hypot(mouse.x-gesture_start.x,mouse.y-gesture_start.y)>4){auto id=*document.selected.begin();if(hit_edge->from.node!=id&&hit_edge->to.node!=id)try{insert_on_edge(document.graph,*hit_edge,id,services.registry);}catch(const std::exception&){} }finish_transform(false);}}
void Editor::draw_selection(ImDrawList* draw){if(!box_select)return;auto mouse=ImGui::GetIO().MousePos;CanvasRect bounds{{std::min(mouse.x,box_start.x),std::min(mouse.y,box_start.y)},{std::max(mouse.x,box_start.x),std::max(mouse.y,box_start.y)}};draw->AddRect(bounds.min,bounds.max,theme::select);if(box_dragging&&ImGui::IsMouseReleased(0)){if(!box_extend)document.selected.clear();for(auto& n:document.graph.nodes)if(node_bounds(n.id).overlaps(bounds))document.selected.insert(n.id);active_node=document.selected.empty()?0:*document.selected.rbegin();box_select=box_dragging=false;}}
}
